public GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // Initialize an empty graph path
    GraphPath<V,E> path = new GraphPath<V,E>(graph);

    // Add the vertices of the tour to the path
    for (E edge : tour) {
        path.addPair(edge.getOriginal(), edge.getDestination());
    }

    // Add the last vertex of the previous edge to the path
    path.addPair(path.getPreviousEdge().getDestination(), path.getPreviousEdge().getSource());

    // Return the resulting path
    return path;
}

