        String line;
        while ((line = reader.readLine()) != null) {
            if (line.startsWith("#")) {
                continue;
            }
            String[] columns = line.split(";");
            if (columns.length != 3) {
                throw new IllegalStateException("Unexpected number of columns in line: " + line);
            }
            long startTimestamp = Long.parseLong(columns[0]);
            long endTimestamp = Long.parseLong(columns[1]);
            String threadName = columns[2];
            // check if the thread belongs to any of the time ranges
            boolean belongsToTimeRange = false;
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (startTimestamp >= timeRange.getStartTime() && endTimestamp <= timeRange.getEndTime()) {
                    belongsToTimeRange = true;
                    break;
                }
            }
            if (belongsToTimeRange) {
                threadSnapshots.add(new ThreadSnapshot(startTimestamp, endTimestamp, threadName));
            }
        }
    }
    return threadSnapshots;
}

